    System.out.println("Rs.5000 to 50000");
else if(gadget.equals("iPad"))
    System.out.println("Rs.10000 to 50000");

switch(gadget) {
    case "Mobile": System.out.println("Rs.5000 to 50000"); break;
    case "iPad": System.out.println("Rs.10000 to 50000"); break;
    default: System.out.println("Not available");
}

